#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    vector<long long> best = a;
    long long answer = 0;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++) {
            if (a[j] < a[i] && best[j] + a[i] > best[i]) best[i] = best[j] + a[i];
        }
        answer = max(answer, best[i]);
    }
    cout << answer << "\n";

    return 0;
}

